// Slated's platform-independent engine for Linux: a JavaScript port of SlatedCore (Swift).
//
// Pure ES module code: no `gi://` imports, no Node built-ins, no DOM. It must run unchanged in GJS
// (the GNOME Shell extension and its preferences), Node and JavaScriptCore (tests on macOS).
// Behavior is pinned to the Swift implementation by the golden vectors in /fixtures (generated by
// `swift run SlatedFixtures`, checked by linux/tests: `make linux-test`).
//
// Data shapes are plain objects matching Slated's config.json (see docs/CONFIG.md):
//
// @typedef {{x: number, y: number, width: number, height: number}} Rect
//   Top-left-origin global coordinates (y grows down), like Mutter's frame rects.
// @typedef {{displayID: number, name: string, frame: Rect, visibleFrame: Rect, isMain: boolean, scale: number}} ScreenInfo
//   `visibleFrame` excludes panels/docks (Mutter's work area). Screens are given in OS order.
// @typedef {Object} Action
//   Canonical JSON form, identical to Swift's Action encoding: {op: "move", x, y, width, height, screen?},
//   {op: "push", direction, style?, screen?}, {op: "by-orientation", landscape: Action, portrait: Action}, …
//   Functions taking an Action also accept any form config.json allows (e.g. a Slate syntax string).
// @typedef {{key: string, modifiers: string[]}} KeyCombo
//   modifiers ⊆ ["ctrl", "alt", "shift", "cmd", "fn"], in that order; "cmd" is Super on Linux.
//   Config strings: "hyper+a".
// @typedef {{severity: "error"|"warning", message: string, file?: string, line?: number}} Diagnostic
// @typedef {{frame: Rect, screens: ScreenInfo[], settings?: Object<string, boolean|number|string>}} WindowContext
//
// Every function below is implemented in a sibling module and re-exported here; callers import only
// from this file. Errors are `SlatedError`s whose `message` matches the macOS app's text.

export {SlatedError} from './errors.js';

// --- Expressions (Slate's expression language) ---------------------------------------------------
/** (expression: string, variables: Object<string, number>) => number. Throws SlatedError("invalidExpression"). */
export {evaluateExpression, validateExpression, windowVariableNames, variableNames} from './expression.js';

// --- Slate syntax ---------------------------------------------------------------------------------
/**
 * parseOperation: "push left bar-resize:screenSizeX/2" → Action. Throws SlatedError.
 * formatOperation: Action → canonical Slate syntax (round-trips with parseOperation).
 * parseKeystroke: "a:ctrl,shift,alt,cmd" / "1:f4,ctrl,alt" → {keys: KeyCombo, modal: {keys: KeyCombo, toggle: boolean} | null}.
 * shellArguments: a `shell` command → [program, ...arguments], split the way Slate ran it (no shell).
 */
export {parseOperation, formatOperation, parseKeystroke, shellArguments} from './slateSyntax.js';
/**
 * parseSlateConfig(text, {path?, homeDirectory?, readFile?}) → {settings, bindings, layouts, defaults, diagnostics}.
 * `readFile(path)` returns the text of a sourced file, or null. describeDiagnostic(d) → ".slate, line 3: …".
 */
export {parseSlateConfig, describeDiagnostic} from './slateConfig.js';

// --- Window math ----------------------------------------------------------------------------------
/**
 * targetFrame(action, context: WindowContext) → Rect, for move/resize/push/nudge/throw/corner/by-orientation;
 *   throws SlatedError("screenNotFound") when the named screen doesn't exist (leave the window alone),
 *   and SlatedError("invalidSyntax") for other actions.
 * targetOrigin(action, context, actualSize: {width, height}) → {x, y}: where to put the window once it
 *   took `actualSize` (apps with minimum sizes).
 * resolveScreen(ref: string|number|null, context) → ScreenInfo | null (null ref = the window's screen).
 * screenContaining(screens, rect) and orderedLeftToRight(screens): Slate's screen helpers.
 */
export {targetFrame, targetOrigin, resolveScreen, screenContaining, orderedLeftToRight} from './frame.js';

// --- Configuration (config.json) ------------------------------------------------------------------
/**
 * decodeConfiguration(text) → configuration with every default filled in (JSON5 comments, trailing
 *   commas, unquoted keys allowed); throws SlatedError("invalidConfiguration") with `codingPath`.
 * encodeConfiguration(config) → stable pretty JSON (sorted keys), byte for byte as Swift writes it.
 * starterConfiguration() → the author's Slate setup in native form (21 Hyper bindings), used on first
 *   run without a Slate config.
 * decodeAction(json) → canonical Action (throws like decodeConfiguration).
 * isWindowGeometry(action) → true for actions that move or resize the focused window (and can be undone).
 * readSettings(settings) → Slate's global settings with typed values and Slate's defaults
 *   (defaultToCurrentScreen, repeatOnHoldOps, secondsBeforeRepeat, undoMaxStackSize, …).
 * randomUUID() → a new binding/hotstring id in Swift's uppercase form (ids must be UUIDs to decode).
 */
export {
  decodeConfiguration,
  encodeConfiguration,
  starterConfiguration,
  decodeAction,
  isWindowGeometry,
  readSettings,
  randomUUID,
} from './config.js';

// --- Keys -----------------------------------------------------------------------------------------
/**
 * parseKeyCombo("hyper+a") → KeyCombo (hyper = ctrl+alt+shift+cmd), or null if invalid.
 * formatKeyCombo(KeyCombo) → "hyper+a" (canonical config string).
 * displayKeyCombo(KeyCombo, {hyperGlyph = true}) → "✦A" / "⌃⌥⇧⌘A".
 * toGnomeAccelerator(KeyCombo | "hyper+a", {hyperMode: "modifiers"|"xkb"}) → "<Control><Alt><Shift><Super>a",
 *   or "<Hyper>a" with hyperMode "xkb"; null when the key has no keysym. `fn` is ignored.
 */
export {parseKeyCombo, formatKeyCombo, displayKeyCombo, toGnomeAccelerator} from './keys.js';

// --- Hotstrings -----------------------------------------------------------------------------------
/**
 * new HotstringMatcher(hotstrings).feed(text, appId) → {hotstring, deleteCount, delimiter} | null;
 *   also update(hotstrings), reset(), backspace().
 * expandTemplate("{date:yyyy-MM-dd}", {now?, clipboard?, locale?, timeZone?}) → expanded text.
 */
export {HotstringMatcher, expandTemplate} from './hotstrings.js';
